	<style>
:root {
  --background: #f1f5f4;
  --surface: #fdfefe;
  --foreground: #22333a;
  --muted: #6b7f88;
  --primary: #22b587;
  --primary-fg: #ffffff;
  --accent: #1793d1;
  --border: rgba(34, 51, 58, 0.1);
  --ease: cubic-bezier(0.32, 0.72, 0, 1);
}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--background);
  color: var(--foreground);
  font-family: "IBM Plex Sans Arabic", system-ui, -apple-system, "Segoe UI", sans-serif;
  line-height: 1.6;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }

.wrap { max-width: 42rem; margin: 0 auto; padding: 0 20px; }

/* Header */
.site-header {
  position: sticky; top: 0; z-index: 30;
  background: rgba(253, 254, 254, 0.85);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}
.site-header .wrap {
  height: 56px; display: flex; align-items: center; justify-content: space-between;
}
.brand { font-size: 18px; font-weight: 700; letter-spacing: -0.01em; }
.header-phone { font-size: 14px; font-weight: 500; color: var(--accent); direction: ltr; }

/* Hero */
.hero { padding: 24px 20px 16px; }
.badge {
  display: inline-flex; align-items: center; gap: 8px;
  background: rgba(34, 181, 135, 0.12); color: var(--primary);
  border-radius: 999px; padding: 6px 12px; font-size: 12px; font-weight: 500;
  margin-bottom: 20px;
}
.badge .dot { width: 6px; height: 6px; border-radius: 999px; background: var(--primary); }
h1 { font-size: 40px; line-height: 1.15; font-weight: 700; margin: 0; letter-spacing: -0.02em; }
.hero p { margin: 16px 0 0; max-width: 34ch; font-size: 15px; color: var(--muted); }

.cta-stack { display: flex; flex-direction: column; gap: 12px; margin-top: 24px; }
.btn {
  display: flex; align-items: center; justify-content: center; gap: 8px;
  border-radius: 16px; padding: 14px 20px; font-size: 15px; font-weight: 500;
  transition: transform .2s var(--ease);
}
.btn:active { transform: scale(0.98); }
.btn-primary { background: var(--primary); color: var(--primary-fg); }
.btn-outline { background: var(--surface); color: var(--foreground); border: 1px solid var(--border); }
.btn svg { width: 20px; height: 20px; }

.hero-media { padding: 0 20px; }
.hero-media .frame { border-radius: 28px; overflow: hidden; border: 1px solid var(--border); }
.hero-media img { width: 100%; height: 300px; object-fit: cover; }
@media (min-width: 600px) { .hero-media img { height: 380px; } }

/* Trust */
.trust { padding: 32px 20px 0; }
.trust-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; text-align: center;
  background: var(--surface); border: 1px solid var(--border); border-radius: 24px; padding: 16px;
}
.trust-grid .cell { padding: 8px 0; }
.trust-grid .cell.mid { border-inline: 1px solid var(--border); }
.trust-grid .num { font-size: 18px; font-weight: 700; }
.trust-grid .lbl { font-size: 11px; color: var(--muted); margin-top: 2px; }

/* Services */
.services { padding: 40px 20px 0; }
h2 { font-size: 24px; font-weight: 700; margin: 0 0 20px; letter-spacing: -0.02em; }
.services-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }
.service {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: 24px; padding: 16px; transition: transform .3s var(--ease);
}
.service:hover { transform: translateY(-4px); }
.service .n {
  width: 44px; height: 44px; border-radius: 16px; display: grid; place-items: center;
  font-size: 14px; font-weight: 700; margin-bottom: 12px;
}
.service .n.p { background: rgba(34, 181, 135, 0.12); color: var(--primary); }
.service .n.a { background: rgba(23, 147, 209, 0.12); color: var(--accent); }
.service h3 { font-size: 15px; font-weight: 700; margin: 0; }
.service p { font-size: 12px; color: var(--muted); margin: 4px 0 0; }

/* Why us */
.why { padding: 40px 20px 0; }
.why-card {
  border-radius: 28px; padding: 24px; border: 1px solid var(--border);
  background: linear-gradient(to bottom, rgba(23, 147, 209, 0.1), var(--surface));
}
.why-kicker { font-size: 11px; letter-spacing: .15em; text-transform: uppercase; color: var(--accent); margin-bottom: 12px; }
.why h3 { font-size: 20px; font-weight: 700; margin: 0; letter-spacing: -0.02em; }
.why ul { list-style: none; margin: 20px 0 0; padding: 0; display: grid; gap: 12px; }
.why li { display: flex; gap: 12px; align-items: flex-start; font-size: 14px; }
.why li::before { content: ""; width: 8px; height: 8px; border-radius: 999px; background: var(--primary); margin-top: 8px; flex: none; }
.why li:nth-child(even)::before { background: var(--accent); }

/* Final CTA */
.final { padding: 40px 20px 112px; }
.final-card {
  background: var(--primary); color: var(--primary-fg);
  border-radius: 28px; padding: 24px; text-align: center;
}
.final-card h3 { font-size: 24px; font-weight: 700; margin: 0; }
.final-card p { font-size: 14px; margin: 8px 0 0; opacity: .85; }
.final-card .btn {
  display: inline-flex; margin-top: 20px; background: var(--surface); color: var(--primary); font-weight: 700;
}

/* Floating buttons (left side) */
.floating { position: fixed; bottom: 32px; left: 16px; z-index: 40; display: flex; flex-direction: column; gap: 12px; }
.floating a { width: 56px; height: 56px; border-radius: 999px; display: grid; place-items: center; }
.floating .call { background: var(--surface); color: var(--accent); border: 1px solid var(--border); animation: pulse-b 2.4s ease-in-out infinite; }
.floating .wa { background: var(--primary); color: var(--primary-fg); animation: pulse-p 2s ease-in-out infinite; }
.floating .call svg { width: 24px; height: 24px; }
.floating .wa svg { width: 28px; height: 28px; }

.site-footer { text-align: center; font-size: 12px; color: var(--muted); padding-bottom: 24px; }

/* Motion */
@keyframes rise { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
@keyframes pulse-p { 0%,100% { box-shadow: 0 0 0 0 rgba(34,181,135,.35); } 50% { box-shadow: 0 0 0 12px rgba(34,181,135,0); } }
@keyframes pulse-b { 0%,100% { box-shadow: 0 0 0 0 rgba(23,147,209,.3); } 50% { box-shadow: 0 0 0 12px rgba(23,147,209,0); } }
.rise { animation: rise .6s var(--ease) both; }

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}

@media (max-width: 380px) {
  h1 { font-size: 34px; }
}
